   "required": true,
   "description": "Access token obtained from simple_note app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "title",
   "type": "string",
   "required": false,
   "description": "Updated title of the note.",
   "default": null,
   "constraints": [
    "length >= 1"
